    if(selection.entries.at(-1)?.jobId===id)playback.append(node("p","This is the selected project export."));else{const use=button("Use this version as export",async()=>{const saved=await adopt({jobId:id,sourceJobId:job.pictureEdit.sequenceId,expectedVersion:selection.version,expectedOutputRevision:job.outputRevision});selection=saved.dialogueSelections;await show(id);tell("Export selected. Earlier rendered versions remain available for comparison or rollback.");});playback.append(use);primary(use);}tell("Rendered edit is ready. Play it through before selecting the project export.");
