  async function compare(a,b){clearTimeout(watchTimer);watched=null;const attempt=++playbackSerial,openedProject=activeProject,jobs=await Promise.all([jobRequest(a),jobRequest(b)]);if(panel.hidden||attempt!==playbackSerial||openedProject!==projectId())return;if(jobs.some(j=>j.status!=="done"||!j.output))throw new Error("Both versions must be completed and available.");const cuts=await Promise.all(jobs.map(job=>request('/versions/'+encodeURIComponent(job.id)+'?outputRevision='+encodeURIComponent(job.outputRevision))));if(panel.hidden||attempt!==playbackSerial||openedProject!==projectId())return;stop(playback);playback.replaceChildren(node("h3","Compare rendered edits"));comparison=mountEditorialComparison({parent:playback,client:previewClient,current:()=>!busy&&!panel.hidden&&attempt===playbackSerial&&openedProject===projectId(),cuts});primary(comparison.playButton);tell("Comparison ready. Choose the soundtrack and press Play to prepare both saved versions.");}
